PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS instruments(id TEXT PRIMARY KEY, market TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, asset_class TEXT NOT NULL CHECK(asset_class='stock'), currency TEXT NOT NULL CHECK(currency='CNY'), provenance TEXT NOT NULL, UNIQUE(market,code));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, owner TEXT NOT NULL, name TEXT NOT NULL, instrument_id TEXT REFERENCES instruments(id), version INTEGER NOT NULL, generation INTEGER NOT NULL DEFAULT 0, lifecycle TEXT NOT NULL, created_at REAL NOT NULL, updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS rule_versions(task_id TEXT REFERENCES tasks(id), version INTEGER NOT NULL, spec TEXT NOT NULL, created_at REAL NOT NULL, change_summary TEXT NOT NULL, PRIMARY KEY(task_id,version));
CREATE TRIGGER IF NOT EXISTS immutable_rule_versions BEFORE UPDATE ON rule_versions BEGIN SELECT RAISE(ABORT,'immutable_rule_version'); END;
CREATE TABLE IF NOT EXISTS runtime(task_id TEXT PRIMARY KEY REFERENCES tasks(id), state TEXT NOT NULL, next_run REAL, lease_token TEXT, lease_until REAL, last_checked REAL, last_success REAL, health TEXT NOT NULL DEFAULT 'pending', decision TEXT, pause_at REAL);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, version INTEGER NOT NULL, generation INTEGER NOT NULL, lease_token TEXT NOT NULL, scheduled_for REAL NOT NULL, started_at REAL NOT NULL, finished_at REAL, status TEXT NOT NULL, result TEXT, decision TEXT, detail TEXT NOT NULL, FOREIGN KEY(task_id,version) REFERENCES rule_versions(task_id,version));
CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY, instrument_id TEXT REFERENCES instruments(id), field TEXT, value TEXT, unit TEXT, source_time TEXT, fetched_at TEXT, provider TEXT, source_ref TEXT, quality TEXT NOT NULL, reason_code TEXT);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, instrument_id TEXT REFERENCES instruments(id), provider TEXT NOT NULL, source_key TEXT NOT NULL, source_time TEXT, fetched_at TEXT, event_type TEXT NOT NULL, UNIQUE(provider,source_key));
CREATE TABLE IF NOT EXISTS calendar_entries(task_id TEXT NOT NULL, version INTEGER NOT NULL, scheduled_at REAL NOT NULL, PRIMARY KEY(task_id,version), FOREIGN KEY(task_id,version) REFERENCES rule_versions(task_id,version));
CREATE TABLE IF NOT EXISTS evidence(id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL REFERENCES runs(id), observation_id TEXT REFERENCES observations(id), event_id TEXT REFERENCES events(id), detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), run_id TEXT NOT NULL REFERENCES runs(id), dedup_key TEXT NOT NULL UNIQUE, created_at REAL NOT NULL, read_at REAL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, task_id TEXT REFERENCES tasks(id), at REAL NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parser_audit(id INTEGER PRIMARY KEY AUTOINCREMENT, at REAL NOT NULL, model TEXT NOT NULL, prompt_version TEXT NOT NULL, outcome TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticks(id TEXT PRIMARY KEY, started_at REAL NOT NULL, finished_at REAL, outcome TEXT);
CREATE INDEX IF NOT EXISTS due_tasks ON runtime(next_run);
CREATE INDEX IF NOT EXISTS task_runs ON runs(task_id,started_at);
CREATE INDEX IF NOT EXISTS task_owner ON tasks(owner,lifecycle);
